# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">THEME 4: DESCRIBING PAST HABITS AND CUSTOMS (USED TO + V1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">GRAMMAR STRUCTURE OF "USED TO"</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Affirmative (+): Subject + used to + V1 (base form)</text>\n  <text x="35" y="108" font-size="10.8" fill="#1e3a8a">  "People used to travel on horseback in the past."</text>\n  <text x="35" y="130" font-size="11.2" fill="#1e3a8a">• Negative (-): Subject + didn\'t use to + V1</text>\n  <text x="35" y="150" font-size="10.8" fill="#1e3a8a">  "People didn\'t use to have smartphones fifty years ago."</text>\n  <text x="35" y="172" font-size="11.2" fill="#1e3a8a">• Question (?): Did + Subject + use to + V1 ...?</text>\n  <text x="35" y="192" font-size="10.8" fill="#1e3a8a">  "Did you use to play marbles in your childhood?"</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">FUNCTIONS AND KEY USAGE RULES</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Past habits that no longer happen today</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• Past states (used to be / used to live / used to have)</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• Contrasting the past with the present ("...but now...")</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• Watch out: Drop "-d" after did / didn\'t → "use to"</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Do NOT confuse with "be / get used to + V-ing"!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«used to + V1» geçmişte düzenli yapılan veya var olan ancak günümüzde sona ermiş alışkanlık ve durumları anlatır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TRADITIONS AND CULTURAL HERITAGE VOCABULARY (ENG.10.4)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">CULTURAL HERITAGE AND TRADITIONS</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• cultural heritage : kültürel miras</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• custom / tradition : gelenek, görenek, âdet</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• pass down (from generation to generation) : nesilden nesile aktarmak</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• handicraft / folk dance : el sanatları / halk oyunları</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• hospitality and respect for elders : misafirperverlik ve büyüklere saygı</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">ANATOLIAN AND WORLD CUSTOMS</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Karagöz and Hacivat shadow play (Gölge oyunu)</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• Ebru (paper marbling) and Pottery (çömlekçilik)</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Copper working (bakırcılık) and Carpet weaving (halı dokuma)</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Serving Turkish coffee with water and Turkish delight</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Henna night (kına gecesi) and Festival gatherings</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Somut olmayan kültürel miras (intangible cultural heritage), toplumların kimliğini geçmişten geleceğe taşır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">COMPARING PAST AND PRESENT LIFESTYLES (THEN VS. NOW)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">LIFE IN THE PAST (USED TO + V1)</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• People used to write letters and wait for weeks.</text>\n  <text x="35" y="112" font-size="11.2" fill="#713f12">• Families used to live in extended family houses.</text>\n  <text x="35" y="136" font-size="11.2" fill="#713f12">• Children used to play outdoor street games.</text>\n  <text x="35" y="160" font-size="11.2" fill="#713f12">• People used to wash clothes by hand and use oil lamps.</text>\n  <text x="35" y="184" font-size="11.2" fill="#713f12">• Neighbours used to gather in courtyards every evening.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">LIFE IN THE PRESENT (SIMPLE PRESENT)</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Today, people send instant messages and emails.</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">• Nowadays, most people live in nuclear family flats.</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• Now, children often play online video games indoors.</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• Today, we use washing machines and smart appliances.</text>\n  <text x="370" y="184" font-size="11.2" fill="#064e3b">• Contrast linkers: whereas, while, however, but now</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Geçmiş ve günümüz karşılaştırılırken geçmiş cümlede «used to + V1», günümüz cümlesinde «Simple Present» kullanılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
